use genewars_assets::{ConqMissionSource,TextStringTable};
use genewars_runtime::{actor_world::ActorWorld,actor_pool::ActorHandleBindings,actor_activation::TrigTables,actor_resources::{ActorAnimationDatabase,actor_resource_spec},blueprint::{BlueprintRng,BlueprintNames},player_state::{PlayerState,ActorOriginSample},physics_tables::PhysicsTables,landing_effect_lifecycle::RetirementUiState};
use std::{fs,path::Path};fn word(b:&[u8],p:usize)->i16{i16::from_le_bytes(b[p..p+2].try_into().unwrap())}
fn main(){let seed=std::env::args().nth(2).unwrap().parse::<u16>().unwrap();let base=std::env::args().nth(1).unwrap();let base=Path::new(&base);let runtime=base.join("private/integration/game-runtime");let bytes=fs::read(runtime.join("terrain/CONQ001.DAT")).unwrap();let src=ConqMissionSource::parse(&bytes).unwrap();let physics=PhysicsTables::from_mapped_bytes(&fs::read(runtime.join("physics/angle.bin")).unwrap(),&fs::read(runtime.join("physics/bounce.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let text=fs::read(runtime.join("menu/text.dat")).unwrap();let strings=TextStringTable::parse(&text).unwrap();let names=BlueprintNames::new(&strings.strings()[..128]).unwrap();let players=std::array::from_fn(|p|PlayerState::fresh_campaign(p as u8,[20736,13568],b"fixture\0").unwrap());let mut world=ActorWorld::from_mission(&src,&[[0;200];20],[ActorHandleBindings::empty();20],players,BlueprintRng{seed,ring:0,draw_count:0}).unwrap();world.admit_creatures(&[[0;124];300]).unwrap();world.admit_effects(&[[0;81];200],[None;200]).unwrap();world.admit_plants(&fs::read(runtime.join("plant-parameters.bin")).unwrap()).unwrap();world.regenerate_player_blueprints(0,[0;36],&names,true).unwrap();let origin=ActorOriginSample{position:[0,0],height:genewars_core::cd_candidate::interpolate_height(world.map(),0,0).unwrap(),shade:genewars_core::cd_candidate::interpolate_entity_shade(world.map(),0,0).unwrap()};world.prepare_fresh_player(0,5,origin,[20736,13568]).unwrap();world.create_landing_core(0,0).unwrap();world.apply_reveal_4096([20736,13568]).unwrap();let context=world.mission_loading_physics();let ui=RetirementUiState::native_empty();for _ in 1..=189{world.step_landing_effect_callbacks(context,&physics,&trig,&ui).unwrap();}
println!("landingseed={} draws={}",world.rng().seed,world.rng().draw_count);
let resources=(0..2).map(|id|{let a=world.actors().record(id).unwrap();let key=world.actors().bindings(id).unwrap().animation_database.unwrap();let spec=actor_resource_spec(key).unwrap();println!("id={id} key={key:?} pos={:?} pending={:?}",[word(a,7),word(a,9)],[word(a,92),word(a,94)]);ActorAnimationDatabase::load(key,fs::read(base.join(format!("private/integration/sprites/{}.anb",spec.decoded_sha256))).unwrap()).unwrap()}).collect::<Vec<_>>();
for frame in 190..=450 {
if frame==190 {let before=world.clone();assert!(world.step_actor_callbacks_in_player_order(4,frame,context,&physics,&trig,&resources[..1],0,0).is_err());assert_eq!(world,before);println!("late resource failure rollback passed");}
if frame==310 {println!("reorder={:?}",world.apply_bounded_move_order_owned(0,0,[20736,13568]).unwrap());}
let callbacks=world.step_actor_callbacks_in_player_order(4,frame,context,&physics,&trig,&resources,0,0).unwrap();
for r in callbacks {let id=r.actor_id;let a=world.actors().record(id as usize).unwrap();println!("frame{frame} id{id} pos={:?} state{} speed{} flags{:04x} smoke{:?}",[word(a,7),word(a,9)],a[85],word(a,65),word(a,73),r.created_effect);}
world.step_landing_effect_callbacks(context,&physics,&trig,&ui).unwrap();}
}
